mapper.update:
/*taskLogHandlerMapper.updateTaskExecutionInfo*/ UPDATE TB_TASK_EXECUTION_HISTORY
EXECUTION_NAME=#{executionName}/*수행타스크이름*/, EXECUTION_START_TIME=#{executionStartTime}/*수행시작일시*/, EXECUTION_END_TIME=#{executionEndTime}/*수행종료일시*/, EXECUTION_SERVER=#{executionServer}/*수행서버*/, EXECUTION_TIME=#{executionTime}/*수행시간*/, EXECUTION_LOG=#{executionLog,jdbcType=CLOB}/*수행로그*/, EXECUTION_LOG=EMPTY_CLOB()/*수행로그EMPTY*/, EXCEPTION_LOG=#{exceptionLog,jdbcType=CLOB}/*예외로그*/, EXCEPTION_LOG=EMPTY_CLOB()/*예외로그EMPTY*/, SYS_UPDATE_DATE=SYSDATE,
WHERE TASK_LOG_NO=#{executionNo,jdbcType=NUMERIC}

/*taskLogHandlerMapper.deleteTaskExecutionInfo*/
DELETE FROM TB_TASK_EXECUTION_HISTORY
WHERE 1=1
AND EXECUTION_NAME=#{executionName}/*수행타스크이름*/
AND TASK_LOG_NO=#{executionNo}
AND SYSDATE-SYS_CREATION_DATE>TO_NUMBER(#{clearBaseDay})
